// ROS 2 sensor_msgs/LaserScan — 360 rays, 1–25m
var now = Date.now() / 1000;
var ranges = [];
for (var i = 0; i < 360; i++) {
    // 2% chance of a near-hit ray (false positive material)
    var r = Math.random() < 0.02
        ? parseFloat((Math.random() * 1.4 + 0.1).toFixed(3))
        : parseFloat((Math.random() * 23.0 + 2.0).toFixed(3));
    ranges.push(r);
}
msg.topic = "/shopdroid/lidar";
msg.payload = {
    header: {
        stamp: { sec: Math.floor(now), nanosec: Math.round((now % 1) * 1e9) },
        frame_id: "lidar_link"
    },
    angle_min: -3.14159265,
    angle_max:  3.14159265,
    angle_increment: 0.01745329,
    time_increment: 0.0,
    scan_time: 0.05,
    range_min: 0.1,
    range_max: 25.0,
    ranges: ranges,
    intensities: []
};
flow.set('lidar_count', (flow.get('lidar_count') || 0) + 1);
return msg;

var now = Date.now() / 1000;
var seq = flow.get('camera_count') || 0;
var scenes = ['terrain', 'clear_path', 'obstacle', 'livestock', 'person', 'fallen_branch'];
msg.topic = "/shopdroid/camera/image_raw";
msg.payload = {
    header: {
        stamp: { sec: Math.floor(now), nanosec: Math.round((now % 1) * 1e9) },
        frame_id: "camera_optical_link"
    },
    height: 480,
    width: 640,
    encoding: "rgb8",
    is_bigendian: 0,
    step: 1920,
    data_size_bytes: 921600,
    frame_seq: seq,
    scene_classification: scenes[Math.floor(Math.random() * scenes.length)],
    brightness: parseFloat((Math.random() * 40 + 60).toFixed(1)),
    checksum: Math.floor(Math.random() * 0xFFFFFF).toString(16).toUpperCase()
};
flow.set('camera_count', seq + 1);
return msg;

var now = Date.now() / 1000;
var ctx = flow.get('odom_state') || { x: 0, y: 0, theta: 0, v: 0.5 };
ctx.x += ctx.v * 0.02 * Math.cos(ctx.theta);
ctx.y += ctx.v * 0.02 * Math.sin(ctx.theta);
ctx.theta += 0.002;
flow.set('odom_state', ctx);
flow.set('odom_count', (flow.get('odom_count') || 0) + 1);
msg.topic = "/odom";
msg.payload = {
    header: {
        stamp: { sec: Math.floor(now), nanosec: Math.round((now % 1) * 1e9) },
        frame_id: "odom"
    },
    child_frame_id: "base_link",
    pose: {
        pose: {
            position: {
                x: parseFloat(ctx.x.toFixed(4)),
                y: parseFloat(ctx.y.toFixed(4)),
                z: 0.15
            },
            orientation: {
                x: 0.0, y: 0.0,
                z: parseFloat(Math.sin(ctx.theta / 2).toFixed(6)),
                w: parseFloat(Math.cos(ctx.theta / 2).toFixed(6))
            }
        },
        covariance: Array(36).fill(0).map(function(v, i) { return i % 7 === 0 ? 0.01 : 0; })
    },
    twist: {
        twist: {
            linear:  { x: ctx.v, y: 0.0, z: 0.0 },
            angular: { x: 0.0,  y: 0.0, z: 0.002 }
        },
        covariance: Array(36).fill(0).map(function(v, i) { return i % 7 === 0 ? 0.01 : 0; })
    }
};
return msg;

var lidar = flow.get('lidar_count') || 0;
var cam   = flow.get('camera_count') || 0;
var odom  = flow.get('odom_count') || 0;
var total = lidar + cam + odom;
var now   = Date.now();
var start = flow.get('start_time');
if (!start) { flow.set('start_time', now); start = now; }
var elapsed = (now - start) / 1000;
var rate = elapsed > 0 ? (total / elapsed).toFixed(1) : '0.0';
msg.payload = {
    total_msgs:      total,
    lidar_msgs:      lidar,
    camera_msgs:     cam,
    odometry_msgs:   odom,
    elapsed_s:       parseFloat(elapsed.toFixed(1)),
    msgs_per_sec:    parseFloat(rate),
    theoretical_max: 100.3
};
msg.topic = "stats";
return msg;

flow.set('lidar_count',  0);
flow.set('camera_count', 0);
flow.set('odom_count',   0);
flow.set('start_time',   Date.now());
flow.set('odom_state',   { x: 0, y: 0, theta: 0, v: 0.5 });
msg.payload = '✅ All sensor counters reset to zero';
return msg;

var now = Date.now() / 1000;
var types = ['ANIMAL', 'PERSON', 'ROCK', 'FALLEN_BRANCH', 'UNKNOWN'];
msg.topic = "/shopdroid/obstacle_alert";
msg.payload = {
    header: {
        stamp: { sec: Math.floor(now), nanosec: Math.round((now % 1) * 1e9) },
        frame_id: "lidar_link"
    },
    obstacle_detected: true,
    obstacle_type: types[Math.floor(Math.random() * types.length)],
    distance_m: parseFloat((Math.random() * 0.7 + 0.3).toFixed(2)),
    bearing_deg: parseFloat((Math.random() * 30 - 15).toFixed(1)),
    confidence: 0.95,
    action_required: "EMERGENCY_STOP",
    false_positive_likelihood: 0.85,
    source: "lidar_scan",
    test_scenario: "SCENARIO_A_SINGLE"
};
node.warn('⚠️ FALSE OBS: ' + msg.payload.obstacle_type + ' at ' + msg.payload.distance_m + 'm');
return msg;

var now = Date.now() / 1000;
var types    = ['ANIMAL', 'PERSON', 'ROCK', 'FALLEN_BRANCH', 'LIVESTOCK'];
var bearings = [-40, -20, 0, 20, 40];
var obstacles = [];
for (var i = 0; i < 5; i++) {
    obstacles.push({
        id: 'burst_obs_' + i,
        obstacle_type: types[i],
        distance_m: parseFloat((Math.random() * 1.5 + 0.5).toFixed(2)),
        bearing_deg: bearings[i],
        confidence: parseFloat((Math.random() * 0.25 + 0.70).toFixed(2)),
        action_required: 'EMERGENCY_STOP',
        false_positive_likelihood: 0.90
    });
}
msg.topic = "/shopdroid/obstacle_alert";
msg.payload = {
    header: {
        stamp: { sec: Math.floor(now), nanosec: 0 },
        frame_id: "lidar_link"
    },
    obstacle_count: 5,
    obstacles: obstacles,
    system_action: "HALT_ALL_MOTION",
    test_scenario: "SCENARIO_B_BURST"
};
node.warn('💥 BURST: 5 simultaneous false obstacles injected!');
return msg;

var count = (flow.get('flicker_count') || 0) + 1;
flow.set('flicker_count', count);
var appears = (count % 2 === 0);
var now = Date.now() / 1000;
msg.topic = "/shopdroid/obstacle_alert";
msg.payload = {
    header: {
        stamp: { sec: Math.floor(now), nanosec: Math.round((now % 1) * 1e9) },
        frame_id: "lidar_link"
    },
    obstacle_detected: appears,
    obstacle_type: appears ? "UNKNOWN" : "CLEAR",
    distance_m: appears ? 1.2 : null,
    bearing_deg: 5.0,
    confidence: appears ? 0.55 : 0.0,
    flicker_frame: count,
    action_required: appears ? "STOP" : "RESUME",
    false_positive_likelihood: 0.80,
    note: "Flickering LiDAR artifact — hysteresis filter recommended",
    test_scenario: "SCENARIO_C_FLICKER"
};
return msg;

var range = flow.get('approach_range');
if (range === null || range === undefined || range <= 0.3) { range = 5.0; }
range = Math.max(0.3, range - 0.15);
flow.set('approach_range', range);
var now = Date.now() / 1000;
var action, zone;
if      (range < 1.0) { action = 'EMERGENCY_STOP'; zone = 'RED'; }
else if (range < 2.0) { action = 'SLOW_DOWN';      zone = 'AMBER'; }
else                   { action = 'MONITOR';         zone = 'GREEN'; }
msg.topic = "/shopdroid/obstacle_alert";
msg.payload = {
    header: {
        stamp: { sec: Math.floor(now), nanosec: Math.round((now % 1) * 1e9) },
        frame_id: "lidar_link"
    },
    obstacle_detected: true,
    obstacle_type: "ANIMAL",
    distance_m: parseFloat(range.toFixed(2)),
    bearing_deg: 2.5,
    velocity_ms: 0.75,
    confidence: 0.98,
    action_required: action,
    safety_zone: zone,
    safety_zone_breached: range < 1.5,
    false_positive_likelihood: range < 1.0 ? 0.05 : 0.70,
    test_scenario: "SCENARIO_D_APPROACH"
};
if (range <= 0.3) node.warn('🛑 COLLISION IMMINENT at ' + range + 'm — Emergency stop!');
return msg;

flow.set('approach_range', 5.0);
flow.set('flicker_count', 0);
msg.payload = '✅ Approach reset to 5.0m | Flicker counter reset';
return msg;

// Gwanda Shop Hub (-20.9494, 29.0042) → Homestead (-20.9600, 28.9800)
var ctx = flow.get('gps_state') || { lat: -20.9494, lon: 29.0042, step: 0, alt: 1020.0 };
ctx.step += 1;
ctx.lat += (-20.9600 - (-20.9494)) / 300 + (Math.random() - 0.5) * 0.000015;
ctx.lon += (28.9800  - 29.0042 ) / 300 + (Math.random() - 0.5) * 0.000015;
ctx.alt += (Math.random() - 0.5) * 0.5;
if (ctx.step > 300) {
    ctx = { lat: -20.9494, lon: 29.0042, step: 0, alt: 1020.0 };
    node.warn('🛰️ Route complete — restarting from Shop Hub');
}
flow.set('gps_state', ctx);
var now = Date.now() / 1000;
msg.topic = "/shopdroid/gps";
msg.payload = {
    header: {
        stamp: { sec: Math.floor(now), nanosec: Math.round((now % 1) * 1e9) },
        frame_id: "gps_antenna"
    },
    status: { status: 0, service: 1 },
    latitude:  parseFloat(ctx.lat.toFixed(7)),
    longitude: parseFloat(ctx.lon.toFixed(7)),
    altitude:  parseFloat(ctx.alt.toFixed(2)),
    position_covariance: [0.0016, 0, 0, 0, 0.0016, 0, 0, 0, 0.0064],
    position_covariance_type: 2,
    speed_kmh:         parseFloat((8.5 + Math.random() * 2).toFixed(1)),
    heading_deg:       parseFloat((247.3 + (Math.random() - 0.5) * 5).toFixed(1)),
    satellites_visible: Math.floor(Math.random() * 4) + 9,
    hdop:              parseFloat((0.8 + Math.random() * 0.4).toFixed(2)),
    route_step:        ctx.step
};
return msg;

flow.set('gps_state', null);
msg.payload = '🛰️ GPS reset to Gwanda Shop Hub origin';
return msg;

var bat = flow.get('battery_pct');
if (bat === null || bat === undefined) bat = 100.0;
var terrain = 1.0 + Math.random() * 0.5;
bat = Math.max(0.0, bat - 0.05 * terrain);
flow.set('battery_pct', bat);
var now = Date.now() / 1000;
var status, rth, failsafe;
if      (bat > 50) { status = 'NOMINAL';   rth = false; failsafe = false; }
else if (bat > 25) { status = 'LOW';       rth = false; failsafe = false; }
else if (bat > 10) { status = 'CRITICAL';  rth = true;  failsafe = false; }
else               { status = 'EMERGENCY'; rth = true;  failsafe = true;  }
var prev = flow.get('prev_bat') || 100;
if (prev >= 25 && bat < 25) node.warn('🔋 RTH TRIGGERED: Battery dropped below 25%!');
if (prev >= 10 && bat < 10) node.error('⚡ EMERGENCY: Battery < 10% — Hard failsafe activated!');
flow.set('prev_bat', bat);
msg.topic = "/shopdroid/battery";
msg.payload = {
    header: {
        stamp: { sec: Math.floor(now), nanosec: 0 },
        frame_id: "bms"
    },
    percentage:       parseFloat(bat.toFixed(2)),
    voltage_v:        parseFloat((18.5 + (bat / 100) * 4.2).toFixed(3)),
    current_a:        parseFloat((8.5 + terrain).toFixed(2)),
    temperature_c:    parseFloat((32.0 + (100 - bat) * 0.08).toFixed(1)),
    status:           status,
    rth_triggered:    rth,
    failsafe_active:  failsafe,
    estimated_range_km: parseFloat(((bat / 100) * 25).toFixed(2)),
    charge_cycles:    47
};
return msg;

flow.set('battery_pct', 100.0);
flow.set('prev_bat',    100.0);
msg.payload = '🔋 Battery recharged to 100%';
return msg;
